`timescale 1ns / 1ps
//////////////////////////////////////////////////////////////////////////////////
// Company: 
// Engineer: 
// 
// Create Date: 10/09/2026 10:21:33 PM
// Design Name: 
// Module Name: conv1_rom
// Description:
//   Stores Conv1 weights and biases generated by the Python golden model.
//   Weight order: [out_channel][in_channel][ky][kx].
//   Conv1 contains 36 signed INT8 weights and 4 signed INT8 biases.
//////////////////////////////////////////////////////////////////////////////////

`default_nettype none
module conv1_rom(
    output wire [287:0] o_weights,
    output wire [31:0] o_biases
    );
   reg signed [7:0] weight_mem [0:35];
   reg signed [7:0] bias_mem [0:3];
   
   
   initial begin
       $readmemh("D:/Share_Data_ubuntu_window/NKKH/data/conv1_weight.hex", weight_mem);
       $readmemh("D:/Share_Data_ubuntu_window/NKKH/data/conv1_bias.hex", bias_mem);
   end
   
   generate
       genvar w;
       for (w=0; w < 36; w = w +1) begin : GEN_WEIGHT_PACK
           assign o_weights[w*8+: 8] = weight_mem[w];
       end
   endgenerate 
    
    generate 
        genvar b;
        for(b=0; b<4; b = b +1) begin : GEN_BIAS_PACK
            assign o_biases[b*8+: 8] = bias_mem[b];
        end
    endgenerate 
           
endmodule
`default_nettype wire